CREATE TABLE "carrera" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre" character varying(100) NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    CONSTRAINT "carrera_nombre_key" UNIQUE (nombre),
    CONSTRAINT "carrera_pkey" PRIMARY KEY (id),
    CONSTRAINT "chk_carrera_nombre" CHECK ((btrim((nombre)::text) <> ''::text))
);

CREATE TABLE "ciclo_academico" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre" character varying(20) NOT NULL,
    "fecha_inicio" date,
    "fecha_fin" date,
    "activo" boolean DEFAULT false NOT NULL,
    CONSTRAINT "ciclo_academico_nombre_key" UNIQUE (nombre),
    CONSTRAINT "ciclo_academico_pkey" PRIMARY KEY (id)
);

CREATE TABLE "ciclo_estudio" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre" character varying(20) NOT NULL,
    "orden" smallint DEFAULT 1 NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    CONSTRAINT "chk_ciclo_estudio_nombre" CHECK ((btrim((nombre)::text) <> ''::text)),
    CONSTRAINT "chk_ciclo_estudio_orden" CHECK ((orden > 0)),
    CONSTRAINT "ciclo_estudio_nombre_key" UNIQUE (nombre),
    CONSTRAINT "ciclo_estudio_pkey" PRIMARY KEY (id)
);

CREATE TABLE "insignia" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre" character varying(60) NOT NULL,
    "descripcion" character varying(255),
    "meta_horas" numeric(6,1) NOT NULL,
    "icono" character varying(60),
    CONSTRAINT "chk_insignia_meta" CHECK ((meta_horas > (0)::numeric)),
    CONSTRAINT "insignia_nombre_key" UNIQUE (nombre),
    CONSTRAINT "insignia_pkey" PRIMARY KEY (id)
);

CREATE TABLE "materia" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre" character varying(100) NOT NULL,
    CONSTRAINT "materia_nombre_key" UNIQUE (nombre),
    CONSTRAINT "materia_pkey" PRIMARY KEY (id)
);

CREATE TABLE "plan" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "nombre" character varying(50) NOT NULL,
    "precio" numeric(8,2) NOT NULL,
    "moneda" character(3) DEFAULT 'PEN'::bpchar NOT NULL,
    "periodo" character varying(60),
    "etiqueta" character varying(30),
    "descripcion" text,
    "activo" boolean DEFAULT true NOT NULL,
    CONSTRAINT "chk_plan_precio" CHECK ((precio >= (0)::numeric)),
    CONSTRAINT "plan_pkey" PRIMARY KEY (id)
);

CREATE TABLE "estudiante" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "correo" character varying(120) NOT NULL,
    "contrasena_hash" character varying(100) NOT NULL,
    "nombre" character varying(100) NOT NULL,
    "carrera" character varying(100),
    "ciclo" character varying(20),
    "bio" text,
    "foto_url" character varying(255),
    "correo_verificado" boolean DEFAULT false NOT NULL,
    "push_activo" boolean DEFAULT true NOT NULL,
    "penalizaciones" integer DEFAULT 0 NOT NULL,
    "cuenta_activa" boolean DEFAULT true NOT NULL,
    "creado_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "nombres" character varying(100),
    "apellidos" character varying(150),
    CONSTRAINT "estudiante_correo_key" UNIQUE (correo),
    CONSTRAINT "estudiante_pkey" PRIMARY KEY (id),
    CONSTRAINT "fk_estudiante_carrera_catalogo" FOREIGN KEY (carrera) REFERENCES carrera(nombre) ON UPDATE CASCADE ON DELETE RESTRICT,
    CONSTRAINT "fk_estudiante_ciclo_catalogo" FOREIGN KEY (ciclo) REFERENCES ciclo_estudio(nombre) ON UPDATE CASCADE ON DELETE RESTRICT
);

CREATE TABLE "plan_beneficio" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "plan_id" bigint NOT NULL,
    "texto" character varying(200) NOT NULL,
    CONSTRAINT "fk_beneficio_plan" FOREIGN KEY (plan_id) REFERENCES plan(id) ON DELETE CASCADE,
    CONSTRAINT "plan_beneficio_pkey" PRIMARY KEY (id)
);

CREATE TABLE "certificado" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "ciclo_id" bigint NOT NULL,
    "codigo" character varying(36) NOT NULL,
    "horas" numeric(10,2) NOT NULL,
    "contenido" bytea NOT NULL,
    "huella" character(64) NOT NULL,
    "firma" bytea,
    "clave_publica" bytea,
    "emitido_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "certificado_ciclo_id_fkey" FOREIGN KEY (ciclo_id) REFERENCES ciclo_academico(id),
    CONSTRAINT "certificado_codigo_key" UNIQUE (codigo),
    CONSTRAINT "certificado_estudiante_id_ciclo_id_key" UNIQUE (estudiante_id, ciclo_id),
    CONSTRAINT "certificado_estudiante_id_fkey" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "certificado_horas_check" CHECK ((horas >= (0)::numeric)),
    CONSTRAINT "certificado_pkey" PRIMARY KEY (id)
);

CREATE TABLE "disponibilidad_horaria" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "dia_semana" smallint NOT NULL,
    "hora_inicio" time without time zone NOT NULL,
    "hora_fin" time without time zone NOT NULL,
    CONSTRAINT "chk_disp_dia" CHECK (((dia_semana >= 1) AND (dia_semana <= 7))),
    CONSTRAINT "chk_disp_orden" CHECK ((hora_fin > hora_inicio)),
    CONSTRAINT "disponibilidad_horaria_pkey" PRIMARY KEY (id),
    CONSTRAINT "fk_disp_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "uq_disp_slot" UNIQUE (estudiante_id, dia_semana, hora_inicio)
);

CREATE TABLE "documento_apoyo" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "nombre_archivo" character varying(255) NOT NULL,
    "formato" character varying(10) NOT NULL,
    "tamano_mb" numeric(5,2) NOT NULL,
    "url_archivo" character varying(500) NOT NULL,
    "subido_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "chk_doc_formato" CHECK (((formato)::text = ANY ((ARRAY['PDF'::character varying, 'DOCX'::character varying, 'PPTX'::character varying])::text[]))),
    CONSTRAINT "chk_doc_tamano" CHECK ((tamano_mb <= 20.00)),
    CONSTRAINT "chk_doc_tamano_positivo" CHECK ((tamano_mb > (0)::numeric)),
    CONSTRAINT "documento_apoyo_pkey" PRIMARY KEY (id),
    CONSTRAINT "fk_doc_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE
);

CREATE TABLE "emparejamiento" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "proponente_id" bigint NOT NULL,
    "receptor_id" bigint NOT NULL,
    "materia_interes_id" bigint,
    "porcentaje_compatibilidad" smallint,
    "mensaje_inicial" text,
    "estado" character varying(15) DEFAULT 'PENDIENTE'::character varying NOT NULL,
    "creado_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "respondido_en" timestamp without time zone,
    CONSTRAINT "chk_match_compatibilidad" CHECK (((porcentaje_compatibilidad >= 0) AND (porcentaje_compatibilidad <= 100))),
    CONSTRAINT "chk_match_distintos" CHECK ((proponente_id <> receptor_id)),
    CONSTRAINT "chk_match_estado" CHECK (((estado)::text = ANY ((ARRAY['SUGERIDO'::character varying, 'PENDIENTE'::character varying, 'ACEPTADO'::character varying, 'RECHAZADO'::character varying])::text[]))),
    CONSTRAINT "emparejamiento_pkey" PRIMARY KEY (id),
    CONSTRAINT "fk_match_materia" FOREIGN KEY (materia_interes_id) REFERENCES materia(id) ON DELETE SET NULL,
    CONSTRAINT "fk_match_proponente" FOREIGN KEY (proponente_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_match_receptor" FOREIGN KEY (receptor_id) REFERENCES estudiante(id) ON DELETE CASCADE
);

CREATE TABLE "estadistica_horas" (
    "estudiante_id" bigint NOT NULL,
    "ciclo_id" bigint NOT NULL,
    "horas_ensenadas" numeric(6,1) DEFAULT 0.0 NOT NULL,
    "horas_aprendidas" numeric(6,1) DEFAULT 0.0 NOT NULL,
    "sesiones_completadas" integer DEFAULT 0 NOT NULL,
    "calificacion_promedio" numeric(3,2),
    CONSTRAINT "chk_esthoras_valores" CHECK (((horas_ensenadas >= (0)::numeric) AND (horas_aprendidas >= (0)::numeric) AND (sesiones_completadas >= 0) AND ((calificacion_promedio IS NULL) OR ((calificacion_promedio >= (1)::numeric) AND (calificacion_promedio <= (5)::numeric))))),
    CONSTRAINT "estadistica_horas_pkey" PRIMARY KEY (estudiante_id, ciclo_id),
    CONSTRAINT "fk_esthoras_ciclo" FOREIGN KEY (ciclo_id) REFERENCES ciclo_academico(id) ON DELETE CASCADE,
    CONSTRAINT "fk_esthoras_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE
);

CREATE TABLE "estudiante_insignia" (
    "estudiante_id" bigint NOT NULL,
    "insignia_id" bigint NOT NULL,
    "obtenida_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "estudiante_insignia_pkey" PRIMARY KEY (estudiante_id, insignia_id),
    CONSTRAINT "fk_estins_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_estins_insignia" FOREIGN KEY (insignia_id) REFERENCES insignia(id) ON DELETE CASCADE
);

CREATE TABLE "estudiante_materia" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "materia_id" bigint NOT NULL,
    "tipo_rol" character varying(10) NOT NULL,
    "nivel" character varying(15) NOT NULL,
    CONSTRAINT "chk_estmat_nivel" CHECK (((nivel)::text = ANY ((ARRAY['BASICO'::character varying, 'INTERMEDIO'::character varying, 'AVANZADO'::character varying])::text[]))),
    CONSTRAINT "chk_estmat_rol" CHECK (((tipo_rol)::text = ANY ((ARRAY['ENSENAR'::character varying, 'APRENDER'::character varying])::text[]))),
    CONSTRAINT "estudiante_materia_pkey" PRIMARY KEY (id),
    CONSTRAINT "fk_estmat_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_estmat_materia" FOREIGN KEY (materia_id) REFERENCES materia(id) ON DELETE CASCADE,
    CONSTRAINT "uq_est_mat_rol" UNIQUE (estudiante_id, materia_id, tipo_rol)
);

CREATE TABLE "intencion_pago" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "plan_id" bigint NOT NULL,
    "monto" numeric(8,2) NOT NULL,
    "estado" character varying(12) DEFAULT 'PENDIENTE'::character varying NOT NULL,
    "creada_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "chk_intpago_estado" CHECK (((estado)::text = ANY ((ARRAY['PENDIENTE'::character varying, 'CANCELADO'::character varying, 'COMPLETADO'::character varying])::text[]))),
    CONSTRAINT "chk_intpago_monto" CHECK ((monto >= (0)::numeric)),
    CONSTRAINT "fk_intpago_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_intpago_plan" FOREIGN KEY (plan_id) REFERENCES plan(id) ON DELETE RESTRICT,
    CONSTRAINT "intencion_pago_pkey" PRIMARY KEY (id)
);

CREATE TABLE "notificacion" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "receptor_id" bigint NOT NULL,
    "titulo" character varying(150) NOT NULL,
    "mensaje" text NOT NULL,
    "tipo_evento" character varying(25),
    "referencia_id" bigint,
    "tipo" character varying(10),
    "canal" character varying(10),
    "estado_envio" character varying(25),
    "dias_aviso" integer,
    "leida" boolean DEFAULT false NOT NULL,
    "creada_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "intentos" integer DEFAULT 0 NOT NULL,
    "proximo_intento_en" timestamp without time zone,
    "ultimo_error" character varying(150),
    CONSTRAINT "chk_notif_canal" CHECK (((canal)::text = ANY ((ARRAY['CORREO'::character varying, 'IN_APP'::character varying, 'AMBOS'::character varying])::text[]))),
    CONSTRAINT "chk_notif_estado" CHECK (((estado_envio)::text = ANY ((ARRAY['ENVIADO'::character varying, 'PENDIENTE_REINTENTO'::character varying, 'GUARDADO_LOCAL'::character varying, 'FALLIDO'::character varying])::text[]))),
    CONSTRAINT "chk_notif_evento" CHECK (((tipo_evento)::text = ANY ((ARRAY['PROPUESTA_SESION'::character varying, 'PROPUESTA_MATCH'::character varying, 'RECORDATORIO'::character varying, 'SISTEMA'::character varying])::text[]))),
    CONSTRAINT "chk_notif_tipo" CHECK (((tipo)::text = ANY ((ARRAY['PUSH'::character varying, 'CORREO'::character varying, 'IN_APP'::character varying])::text[]))),
    CONSTRAINT "fk_notif_receptor" FOREIGN KEY (receptor_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "notificacion_pkey" PRIMARY KEY (id)
);

CREATE TABLE "sesion" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "proponente_id" bigint NOT NULL,
    "receptor_id" bigint NOT NULL,
    "materia_id" bigint NOT NULL,
    "ciclo_id" bigint,
    "fecha_hora" timestamp without time zone NOT NULL,
    "duracion_programada_min" integer DEFAULT 60 NOT NULL,
    "estado" character varying(20) NOT NULL,
    "enlace_videollamada" character varying(255),
    "inicio_real" timestamp without time zone,
    "fin_real" timestamp without time zone,
    "duracion_real_min" integer,
    "origen_duracion" character varying(10),
    "marca_proponente" boolean DEFAULT false NOT NULL,
    "marca_receptor" boolean DEFAULT false NOT NULL,
    "estado_calificacion" character varying(10) DEFAULT 'PENDIENTE'::character varying NOT NULL,
    "mentor_id" bigint NOT NULL,
    "aprendiz_id" bigint NOT NULL,
    "creada_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    "reprogramaciones" integer DEFAULT 0 NOT NULL,
    "revision_horas" boolean DEFAULT false NOT NULL,
    CONSTRAINT "chk_sesion_calif" CHECK (((estado_calificacion)::text = ANY ((ARRAY['PENDIENTE'::character varying, 'CALIFICADA'::character varying, 'EXPIRADA'::character varying])::text[]))),
    CONSTRAINT "chk_sesion_distintos" CHECK ((proponente_id <> receptor_id)),
    CONSTRAINT "chk_sesion_duraciones" CHECK (((duracion_programada_min > 0) AND ((duracion_real_min IS NULL) OR (duracion_real_min >= 0)))),
    CONSTRAINT "chk_sesion_estado" CHECK (((estado)::text = ANY ((ARRAY['PROPUESTA'::character varying, 'CONFIRMADA'::character varying, 'EN_CURSO'::character varying, 'COMPLETADA'::character varying, 'CANCELADA'::character varying])::text[]))),
    CONSTRAINT "chk_sesion_fechas" CHECK (((fin_real IS NULL) OR ((inicio_real IS NOT NULL) AND (fin_real >= inicio_real)))),
    CONSTRAINT "chk_sesion_origen" CHECK (((origen_duracion)::text = ANY ((ARRAY['REAL'::character varying, 'ESTIMADO'::character varying, 'REVISADO'::character varying])::text[]))),
    CONSTRAINT "chk_sesion_roles" CHECK ((((mentor_id = proponente_id) AND (aprendiz_id = receptor_id)) OR ((mentor_id = receptor_id) AND (aprendiz_id = proponente_id)))),
    CONSTRAINT "fk_sesion_ciclo" FOREIGN KEY (ciclo_id) REFERENCES ciclo_academico(id) ON DELETE SET NULL,
    CONSTRAINT "fk_sesion_materia" FOREIGN KEY (materia_id) REFERENCES materia(id) ON DELETE RESTRICT,
    CONSTRAINT "fk_sesion_proponente" FOREIGN KEY (proponente_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_sesion_receptor" FOREIGN KEY (receptor_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "sesion_aprendiz_id_fkey" FOREIGN KEY (aprendiz_id) REFERENCES estudiante(id),
    CONSTRAINT "sesion_mentor_id_fkey" FOREIGN KEY (mentor_id) REFERENCES estudiante(id),
    CONSTRAINT "sesion_pkey" PRIMARY KEY (id)
);

CREATE TABLE "solicitud_soporte" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "reportado_id" bigint,
    "tipo" character varying(10) NOT NULL,
    "categoria" character varying(100) NOT NULL,
    "asunto" character varying(150) NOT NULL,
    "mensaje" character varying(2000) NOT NULL,
    "estado" character varying(10) DEFAULT 'PENDIENTE'::character varying NOT NULL,
    "creado_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "prioridad" character varying(20) DEFAULT 'NORMAL'::character varying NOT NULL,
    CONSTRAINT "solicitud_soporte_check" CHECK (((reportado_id IS NULL) OR (reportado_id <> estudiante_id))),
    CONSTRAINT "solicitud_soporte_estado_check" CHECK (((estado)::text = ANY ((ARRAY['PENDIENTE'::character varying, 'RESUELTO'::character varying, 'CERRADO'::character varying])::text[]))),
    CONSTRAINT "solicitud_soporte_estudiante_id_fkey" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "solicitud_soporte_pkey" PRIMARY KEY (id),
    CONSTRAINT "solicitud_soporte_reportado_id_fkey" FOREIGN KEY (reportado_id) REFERENCES estudiante(id) ON DELETE SET NULL,
    CONSTRAINT "solicitud_soporte_tipo_check" CHECK (((tipo)::text = ANY ((ARRAY['SOPORTE'::character varying, 'REPORTE'::character varying])::text[])))
);

CREATE TABLE "suscripcion" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "plan_id" bigint,
    "estado" character varying(10) NOT NULL,
    "es_trial" boolean DEFAULT false NOT NULL,
    "fecha_inicio" date NOT NULL,
    "fecha_vencimiento" date,
    CONSTRAINT "chk_susc_estado" CHECK (((estado)::text = ANY ((ARRAY['TRIAL'::character varying, 'ACTIVO'::character varying, 'GRATUITO'::character varying, 'EXPIRADO'::character varying])::text[]))),
    CONSTRAINT "chk_susc_fechas" CHECK (((fecha_vencimiento IS NULL) OR (fecha_vencimiento >= fecha_inicio))),
    CONSTRAINT "fk_susc_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_susc_plan" FOREIGN KEY (plan_id) REFERENCES plan(id) ON DELETE SET NULL,
    CONSTRAINT "suscripcion_pkey" PRIMARY KEY (id)
);

CREATE TABLE "token_seguridad" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "estudiante_id" bigint NOT NULL,
    "codigo" character varying(100) NOT NULL,
    "tipo" character varying(20) NOT NULL,
    "expira_en" timestamp without time zone NOT NULL,
    "usado" boolean DEFAULT false NOT NULL,
    "creado_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "chk_token_tipo" CHECK (((tipo)::text = ANY ((ARRAY['VERIFICACION_CORREO'::character varying, 'RECUPERACION_CLAVE'::character varying])::text[]))),
    CONSTRAINT "fk_token_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "token_seguridad_pkey" PRIMARY KEY (id)
);

CREATE TABLE "calificacion" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "sesion_id" bigint NOT NULL,
    "calificador_id" bigint NOT NULL,
    "estrellas" smallint NOT NULL,
    "anonimo" boolean DEFAULT false NOT NULL,
    "creada_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "calificacion_pkey" PRIMARY KEY (id),
    CONSTRAINT "chk_calif_estrellas" CHECK (((estrellas >= 1) AND (estrellas <= 5))),
    CONSTRAINT "fk_calif_estudiante" FOREIGN KEY (calificador_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_calif_sesion" FOREIGN KEY (sesion_id) REFERENCES sesion(id) ON DELETE CASCADE,
    CONSTRAINT "uq_sesion_calificador" UNIQUE (sesion_id, calificador_id)
);

CREATE TABLE "conversacion" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "sesion_id" bigint,
    "emparejamiento_id" bigint,
    "estudiante_a" bigint NOT NULL,
    "estudiante_b" bigint NOT NULL,
    "estado" character varying(10) DEFAULT 'ACTIVA'::character varying NOT NULL,
    "creada_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "chk_conv_distintos" CHECK ((estudiante_a <> estudiante_b)),
    CONSTRAINT "chk_conv_estado" CHECK (((estado)::text = ANY ((ARRAY['ACTIVA'::character varying, 'FINALIZADO'::character varying])::text[]))),
    CONSTRAINT "conversacion_pkey" PRIMARY KEY (id),
    CONSTRAINT "fk_conv_est_a" FOREIGN KEY (estudiante_a) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_conv_est_b" FOREIGN KEY (estudiante_b) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_conv_match" FOREIGN KEY (emparejamiento_id) REFERENCES emparejamiento(id) ON DELETE SET NULL,
    CONSTRAINT "fk_conv_sesion" FOREIGN KEY (sesion_id) REFERENCES sesion(id) ON DELETE SET NULL
);

CREATE TABLE "pago" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "intencion_id" bigint,
    "estudiante_id" bigint NOT NULL,
    "plan_id" bigint NOT NULL,
    "modalidad" character varying(10),
    "monto" numeric(8,2) NOT NULL,
    "moneda" character(3) DEFAULT 'PEN'::bpchar NOT NULL,
    "ultimos_digitos" character(4),
    "marca_tarjeta" character varying(20),
    "titular" character varying(100),
    "codigo_autorizacion" character varying(30),
    "estado" character varying(12) NOT NULL,
    "motivo_fallo" character varying(200),
    "numero_comprobante" character varying(20),
    "pagado_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "chk_pago_estado" CHECK (((estado)::text = ANY ((ARRAY['COMPLETADO'::character varying, 'RECHAZADO'::character varying, 'TIMEOUT'::character varying])::text[]))),
    CONSTRAINT "chk_pago_modalidad" CHECK (((modalidad)::text = ANY ((ARRAY['MENSUAL'::character varying, 'SEMESTRAL'::character varying])::text[]))),
    CONSTRAINT "chk_pago_monto" CHECK ((monto >= (0)::numeric)),
    CONSTRAINT "fk_pago_estudiante" FOREIGN KEY (estudiante_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "fk_pago_intencion" FOREIGN KEY (intencion_id) REFERENCES intencion_pago(id) ON DELETE SET NULL,
    CONSTRAINT "fk_pago_plan" FOREIGN KEY (plan_id) REFERENCES plan(id) ON DELETE RESTRICT,
    CONSTRAINT "pago_numero_comprobante_key" UNIQUE (numero_comprobante),
    CONSTRAINT "pago_pkey" PRIMARY KEY (id)
);

CREATE TABLE "comentario" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "calificacion_id" bigint NOT NULL,
    "texto" text NOT NULL,
    "estado" character varying(25) DEFAULT 'PENDIENTE_MODERACION'::character varying NOT NULL,
    "creado_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "chk_com_estado" CHECK (((estado)::text = ANY ((ARRAY['APROBADO'::character varying, 'PENDIENTE_MODERACION'::character varying, 'RECHAZADO'::character varying])::text[]))),
    CONSTRAINT "comentario_calificacion_id_key" UNIQUE (calificacion_id),
    CONSTRAINT "comentario_pkey" PRIMARY KEY (id),
    CONSTRAINT "fk_com_calificacion" FOREIGN KEY (calificacion_id) REFERENCES calificacion(id) ON DELETE CASCADE
);

CREATE TABLE "mensaje" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "conversacion_id" bigint NOT NULL,
    "emisor_id" bigint NOT NULL,
    "texto" text NOT NULL,
    "leido" boolean DEFAULT false NOT NULL,
    "enviado_en" timestamp without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "fk_msj_conversacion" FOREIGN KEY (conversacion_id) REFERENCES conversacion(id) ON DELETE CASCADE,
    CONSTRAINT "fk_msj_emisor" FOREIGN KEY (emisor_id) REFERENCES estudiante(id) ON DELETE CASCADE,
    CONSTRAINT "mensaje_pkey" PRIMARY KEY (id)
);
